INSERT INTO periods (period_id, period_name, start_year, end_year) VALUES
 ('PER_NABATAEAN','Nabataean Kingdom',-312,106),
 ('PER_DMT_AKSUM','Dʿmt and Pre-Christian Aksum',-800,400)
INSERT INTO sources (source_id, source_type, title, scope) VALUES
 ('SRC_MUNRO_HAY_AKSUM','secondary scholarship','Stuart Munro-Hay, Aksum: An African Civilisation of Late Antiquity','Aksumite'),
 ('SRC_VENTRIS_CHADWICK','secondary scholarship','Michael Ventris & John Chadwick, Documents in Mycenaean Greek','Mycenaean'),
 ('SRC_HODDINOTT_THRACIANS','secondary scholarship','R. F. Hoddinott, The Thracians','Thracian'),
 ('SRC_TEIXIDOR_PALMYRA','secondary scholarship','Javier Teixidor, The Pantheon of Palmyra','Aramean')
INSERT INTO _e VALUES
 ('ENT_NAB_PANTHEON','The Nabataean Pantheon','Nabataean','Collective','Pantheon','pantheon; Nabataean state religion; caravan trade; sacred kingship','A','Collective grouping the deities worshipped across the Nabataean kingdom from Petra and Bostra to Hegra (Madaʾin Salih), attested in Nabataean Aramaic inscriptions and rock-cut sanctuaries.'),
 ('ENT_NAB_SHAI_AL_QAUM','Shai al-Qaum','Nabataean','Tutelary deity','Deity','protection; caravans; warriors; abstinence from wine','A','Caravan-protector and warrior god ''who drinks no wine and builds no tomb,'' named in a bilingual Nabataean altar from Palmyra (CIS II 3978).'),
 ('ENT_NAB_ARA','Aʿra','Nabataean','God','City god','tutelary city-god; sovereignty; sacred mountain','B','Tutelary god of Bostra closely associated with Dushara, who is titled ''the god of our lord who is in Bostra'' in Nabataean Hawran inscriptions.'),
 ('ENT_NAB_AL_KUTBA','al-Kutbaʾ','Nabataean','Deity','Deity','writing; commerce; fate; accounting','A','Scribal and commerce deity (Nabataean counterpart of Babylonian Nabu / Greek Hermes), attested at Petra, Hegra and Sinai; sometimes the goddess al-Kutbay.'),
 ('ENT_NAB_MANOTU','Manotu','Nabataean','Goddess','Deity','fate; death; tomb protection; retribution','A','Hegran cult-form of the fate-goddess Manat, invoked as ''Manotu and her Qaisha'' in the tomb-curse inscriptions of Hegra to protect burials.'),
 ('ENT_NAB_AL_UZZA_PETRA','al-ʿUzza of Petra','Nabataean','Goddess','Deity','love; Venus; fertility; royal patroness','B','Petraean cult-form of al-ʿUzza, chief Nabataean goddess identified with Aphrodite, associated with Petra''s Temple of the Winged Lions.'),
 ('ENT_ARAB_KAABA_IDOLS','The Idols of the Kaʿba and the Arabian Sanctuaries','Pre-Islamic Arabian','Collective','Pantheon','idol cult; tribal patron deities; Arabian sanctuaries','A','Collective of the betyls and idols of the Hijaz and wider Arabia catalogued in Ibn al-Kalbi''s Kitab al-Asnam and reflected in Qurʾan 71:23.'),
 ('ENT_ARAB_ISAF','Isāf','Pre-Islamic Arabian','Sacred betyl','Deity','sanctuary guardian; ritual; petrified ancestor','B','Idol at the Kaʿba; in tradition a man petrified for sacrilege, paired with Nāʾila, attested in Ibn al-Kalbi at al-Safa/al-Marwa.'),
 ('ENT_ARAB_NAILA','Nāʾila','Pre-Islamic Arabian','Sacred betyl','Deity','sanctuary guardian; ritual; petrified ancestor','B','Female idol at the Kaʿba, paired with Isāf as a petrified couple, attested in Ibn al-Kalbi at al-Safa/al-Marwa.'),
 ('ENT_ARAB_MANAF','Manāf','Pre-Islamic Arabian','Deity','Deity','tribal patron; honour; high status','B','Meccan deity whose name survives in the Quraysh name ʿAbd Manaf; listed among the gods of Mecca in Ibn al-Kalbi.'),
 ('ENT_ARAB_DHUL_KHALASA','Dhu''l-Khalasa','Pre-Islamic Arabian','Sacred betyl','Deity','oracle; divination; tribal sanctuary','B','White quartz betyl and oracular sanctuary at Tabala in Yemen, ''the Yemeni Kaʿba,'' venerated by Daws, Khathʿam and Bajila per Ibn al-Kalbi.'),
 ('ENT_ARAB_RUDA','Ruda','Pre-Islamic Arabian','Astral deity','Deity','Venus; evening star; benevolence; fortune','A','North Arabian astral deity (Venus) attested in Thamudic and Safaitic inscriptions and named in Assyrian records as ''Ruldaiu''; also in Ibn al-Kalbi.'),
 ('ENT_ARAB_NUHM','Nuhm','Pre-Islamic Arabian','Deity','Deity','tribal patron; protection','B','Deity of the Muzayna tribe whose name survives in the theophoric ʿAbd Nuhm; listed in Ibn al-Kalbi.'),
 ('ENT_ARAB_AL_FALS','al-Fals','Pre-Islamic Arabian','Sacred betyl','Deity','tribal patron; sanctuary; asylum','B','Idol of the Tayyiʾ tribe, a reddish rock outcrop on Jabal Aja serving as a place of asylum, described in Ibn al-Kalbi.'),
 ('ENT_ARAB_SAD','Saʿd','Pre-Islamic Arabian','Sacred betyl','Deity','tribal patron; fortune; good luck','B','A tall rock idol of the Banu Milkan (Kinana) on which sacrificial blood was poured, attested in Ibn al-Kalbi.'),
 ('ENT_ARAB_QUZAH','Quzaḥ','Pre-Islamic Arabian','Astral deity','Deity','storm; rainbow; weather; Muzdalifa rites','B','Storm/rainbow deity associated with the hill Quzaḥ at Muzdalifa near Mecca; Arabic qaws Quzaḥ (''Quzaḥ''s bow'' = rainbow) preserves his name.'),
 ('ENT_ARAB_SUWA','Suwāʿ','Pre-Islamic Arabian','Deity','Deity','antediluvian idol; tribal patron','A','One of the five antediluvian idols of Qurʾan 71:23; later the idol of the Hudhayl tribe at Ruhat per Ibn al-Kalbi.'),
 ('ENT_ARAB_YAUQ','Yaʿūq','Pre-Islamic Arabian','Deity','Deity','antediluvian idol; tribal patron; protection','A','One of the five antediluvian idols of Qurʾan 71:23 (''the preventer/protector''); horse-formed idol of Hamdan at Khaywan in Yemen per Ibn al-Kalbi.'),
 ('ENT_SAB_WADD','Wadd','South Arabian','National deity','Deity','moon; love; protection; covenant','A','National god of the Minaean (Maʿin) kingdom and a moon-deity; the formula ''Wd ʾb'' (Wadd is father) is widely attested on amulets and inscriptions; one of the five idols of Qurʾan 71:23.'),
 ('ENT_SAB_ANBAY','Anbay','South Arabian','Deity','Deity','justice; oracle; prophecy; law','B','Qatabanian oracular and law-giving god, paired with Ḥawkam; ''Anbay and Ḥawkam'' issue decrees in Qatabanian legal inscriptions.'),
 ('ENT_SAB_SAYIN','Sayin','South Arabian','National deity','Deity','sun; sovereignty; protection','A','National god of the kingdom of Hadramawt, attested in royal dedications and the great temple at Shabwa; a solar/national patron of Hadramite kingship.'),
 ('ENT_SAB_SIN_HAWL','Sin (Hawl)','South Arabian','Astral deity','Deity','moon; sovereignty','B','Moon-god of Hadramawt bearing the epithet Hawl, attested at Shabwa; distinct from the Mesopotamian Sin though sharing the lunar name.'),
 ('ENT_SAB_TALAB','Taʾlab Riyam','South Arabian','Deity','Deity','protection; fertility; moon; tutelary','A','Tutelary god of the Sabaean tribe Banu Sumʿay, titled ''Taʾlab Riyam'' after his sanctuary on the Riyam massif; many oracle and pilgrimage inscriptions record his cult.'),
 ('ENT_SAB_HAWBAS','Hawbas','South Arabian','Deity','Deity','fertility; moon','B','Sabaean deity closely associated with Almaqah, frequently named alongside him at Awwam/Marib and in Dʿmt-period Ethiopia.'),
 ('ENT_SAB_DHAT_HIMYAM','Dhāt-Ḥimyam','South Arabian','Astral deity','Deity','sun; fertility','B','One of the two solar ''Ladies'' (Dhat = ''She of'') of the Sabaean pantheon, a hypostasis of the sun-goddess; her cult was carried to Dʿmt-period Ethiopia.'),
 ('ENT_SAB_DHAT_BADAN','Dhāt-Baʿdan','South Arabian','Astral deity','Deity','sun; fertility','B','The second solar ''Lady'' of the Sabaean pantheon, paired with Dhat-Himyam; both invoked in temple dedications such as those from the Awwam sanctuary.'),
 ('ENT_SAB_DHAT_ZAHRAN','Dhāt-Ẓahrān','South Arabian','Astral deity','Deity','sun','C','A further solar ''Lady'' epithet of the South-Arabian sun-goddess attested in dedicatory inscriptions, a localized hypostasis of Shams.'),
 ('ENT_SAB_BASAMUM','Basamum','South Arabian','Deity','Deity','healing','B','South-Arabian god of healing, his name connected to the balsam/aromatic plant (bsm); attested in votive cure-texts.'),
 ('ENT_SAB_NASR','Nasr','South Arabian','Deity','Deity','protection; vulture/eagle form','C','A South/West-Arabian deity (''vulture/eagle'') named in Qurʾan 71:23 and attested in onomastics; venerated in the Himyaritic/Yemeni sphere.'),
 ('ENT_SAB_YAGHUTH','Yagūth','South Arabian','Deity','Deity','protection; aid in war; lion form','C','Pre-Islamic deity (''he helps'') named in Qurʾan 71:23 alongside Yaʿuq and Nasr; lion-idol of Madhhij/Murad in Yemen per Ibn al-Kalbi.'),
 ('ENT_AKS_PANTHEON','The Pre-Christian Aksumite Pantheon','Aksumite','Collective','Pantheon','pantheon; Dʿmt and Aksumite religion','A','The pagan deities worshipped in the Dʿmt kingdom and pre-Christian Aksum, attested in the pre-monotheist inscriptions of King Ezana and in Dʿmt-period South-Arabian-derived dedications.'),
 ('ENT_AKS_MAHREM','Mahrem','Aksumite','War deity','Deity','war; sovereignty; protection; royal patron','A','Chief god and divine ancestor of the Aksumite kings, ''invincible to the enemy''; Ezana''s Greek inscription equates him with Ares and styles the king ''son of Mahrem''.'),
 ('ENT_AKS_ASTAR','Astar','Aksumite','Astral deity','Deity','Venus; sky','A','Aksumite reflex of the South-Arabian astral god ʿAthtar (Venus), named first in Ezana''s pre-Christian triad ''Astar, Beher and Medr''.'),
 ('ENT_AKS_BEHER','Beher','Aksumite','Deity','Deity','sea; water; land','B','Aksumite god of the sea (later ''land/country''), named in Ezana''s triad; in the Greek version the maritime deity corresponds to Poseidon.'),
 ('ENT_AKS_MEDR','Medr','Aksumite','Deity','Deity','earth; fertility','B','Aksumite earth god (Geʿez medr = ''earth/land''), the third member of Ezana''s pre-Christian triad, aligned with the Greek earth deity.'),
 ('ENT_ARA_BEL_PALMYRA','Bel of Palmyra','Aramean','God','Sovereignty Deity','sovereignty; sky; cosmic order','A','Head of the Palmyrene pantheon, worshipped in the great Temple of Bel (dedicated 32 CE); a Bel form assimilated to Babylonian Bel-Marduk, heading the astral triad with Yarhibol and Aglibol.'),
 ('ENT_ARA_YARHIBOL','Yarhibol','Aramean','Astral deity','Solar Deity','sun; oracle; springs','A','Palmyrene solar god, originally guardian of the sacred spring Efqa, depicted with a radiate nimbus and flanking Bel in the Temple of Bel.'),
 ('ENT_ARA_AGLIBOL','Aglibol','Aramean','Astral deity','Lunar Deity','moon','A','Palmyrene lunar god depicted with a crescent, paired with Malakbel in the Sacred Garden cult and flanking Bel in the Temple of Bel.'),
 ('ENT_ARA_MALAKBEL','Malakbel','Aramean','Astral deity','Solar Deity','sun; vegetation; fertility','A','Palmyrene solar and vegetation god (''Messenger of Bel''), paired with Aglibol; the bilingual altar in Rome equates him with Sol Sanctissimus.'),
 ('ENT_ARA_ALLAT_PALMYRA','Allat of Palmyra','Aramean','Goddess','War Deity','war; protection','A','Arab goddess worshipped at Palmyra in her own sanctuary, assimilated to armed Athena, attested in Palmyrene and bilingual dedications.'),
 ('ENT_ARA_SIN_HARRAN','Sin of Harran','Aramean','Astral deity','Lunar Deity','moon; kingship; oaths','A','The moon god of the Ehulhul sanctuary at Harran, the principal lunar cult of the Aramean/Assyrian north; named in the Sefire treaty curses and rebuilt by Nabonidus.'),
 ('ENT_ARA_RAKIB_EL','Rakib-El','Aramean','Dynastic god','Sovereignty Deity','kingship; dynastic protection','A','''Charioteer of El'', tutelary dynastic god of the kings of Samʾal/Zincirli, named in the 8th-c. BCE Hadad, Panamuwa and Kilamuwa inscriptions.'),
 ('ENT_ARA_SAHAR','Sahar','Aramean','Astral deity','Lunar Deity','moon','B','Aramean moon deity (Aramaic shr, ''crescent'') invoked among the gods of the royal house at Samʾal in the Panamuwa inscriptions of Zincirli.'),
 ('ENT_ARA_KUBABA','Kubaba of Carchemish','Aramean','City god','Tutelary Deity','protection; sovereignty','A','Tutelary goddess of Carchemish, a leading deity of the Syro-Hittite/Aramean north in Luwian and Aramaic inscriptions; later underlies Anatolian Kybele.'),
 ('ENT_ARA_ELAGABAL','Elagabal of Emesa','Aramean','Astral deity','Solar Deity','sun','A','The sun god of Emesa (''Ila gabal, god of the mountain'') worshipped as a conical black betyl; his priest-emperor Elagabalus installed the stone in Rome, attested on coinage and by Herodian.'),
 ('ENT_ARA_AZIZOS','Azizos','Aramean','Astral deity','Astral Deity','morning star; war; protection','B','The morning-star deity of Edessa, paired with Monimos as the two attendants of the sun; identified with Venus/Phosphoros by Julian (Hymn to King Helios).'),
 ('ENT_ARA_MONIMOS','Monimos','Aramean','Astral deity','Astral Deity','evening star; protection','B','The evening-star deity of Edessa (Aramaic mnʿm, ''the favourable one''), twin attendant of the sun alongside Azizos, named by Julian (Hymn to King Helios).'),
 ('ENT_URA_TRIAD','The Supreme Triad of Urartu','Urartian','Collective','Deity collective','national pantheon; divine hierarchy; sovereignty; war; storm; sun','A','The organizing triad of the Urartian state pantheon — Khaldi (supreme/war), Teisheba (storm), Shivini (sun) — opening the 79-deity Meher Kapisi god-list of Ishpuini and Minua.'),
 ('ENT_URA_BAGMASHTU','Bagmashtu','Urartian','Deity','Consort goddess','consort of Khaldi; fertility; regional cult','B','Consort of Khaldi at Musasir (Ardini); where most of Urartu names Arubani as Khaldi''s wife, Musasir dedications name ''Khaldi and his wife Bagmashtu'', a regional consort tradition.'),
 ('ENT_URA_SELARDI','Selardi','Urartian','Lunar deity','Moon deity','moon; lunar cycle; night sky','C','Urartian moon deity named in the Meher Kapisi god-list; gender and full role debated, attestation limited to the divine list.'),
 ('ENT_URA_TUSHPUEA','Tushpuea','Urartian','Deity','Consort goddess','consort of Shivini; the city of Tushpa','C','Urartian goddess listed third in the female-deity sequence of the Meher Kapisi inscription (paralleling Shivini); the capital Tushpa is held to derive its name from her.'),
 ('ENT_URA_HUBA','Huba','Urartian','Deity','Consort goddess','consort of Teisheba','C','Consort of the storm-god Teisheba in the Urartian god-list, corresponding to Hurrian Hepat, consort of Teshub, consistent with Teisheba being the Urartian reception of Teshub.'),
 ('ENT_URA_SARDI','Sardi','Urartian','Astral deity','Astral deity','stars; astral order; night sky','C','Urartian astral/star deity named in the Meher Kapisi god-list, identified by a single domain and a sacrifice allotment with no surviving narrative.'),
 ('ENT_URA_SPEAR_KHALDI','The Spear of Khaldi','Urartian','Cult object','Sacred weapon','war; divine victory; royal legitimation; weapon cult','B','The lance of Khaldi was a sacred weapon embodying the war-god''s power; the Karagunduz stele praises it as victorious, and Khaldi''s temples were ''houses of weapons''.'),
 ('ENT_IB_COSUS','Cosus','Iberian/Lusitanian','War deity','War Deity','war; battle; warrior protection; tribal defence','A','War-god attested by ~20 Latin votive inscriptions in Galicia and northern Portugal, interpreted via interpretatio romana as a Mars-type god of the Callaeci; sometimes identified with Cariociecus.'),
 ('ENT_IB_REUE','Reue','Iberian/Lusitanian','Supreme god','Sky Deity','sky; supreme deity; sovereignty; sacrifice-recipient','A','Supreme/sky deity (from IE *dyeu-) in Lusitanian ritual texts including the Cabeço das Fraguas inscription and Arronches plaque, with epithets Reve Anabaraego and Reve Larauco.'),
 ('ENT_IB_RUNESOCESIUS','Runesocesius','Iberian/Lusitanian','War deity','War Deity','war; javelin; weapons; warrior cult','B','War/javelin god attested at the São Miguel da Mota / Alentejo cult region, connected to the Endovelicus sanctuary complex.'),
 ('ENT_IB_BORMANICUS','Bormanicus','Iberian/Lusitanian','Spring deity','Water Deity','thermal springs; healing waters; medicinal baths','A','Thermal-spring/healing-waters god attested at the hot-spring sanctuary of Caldas de Vizela; of the Celtic Bormo/Borvo family of spring deities.'),
 ('ENT_IB_TONGOENABIAGUS','Tongoenabiagus','Iberian/Lusitanian','Spring deity','Water Deity','springs; sacred water source; oaths','B','Spring deity attested at a sacred spring beside the river Cávado at Braga; the -nabiagus element links it to the Nabia water-deity family.'),
 ('ENT_IB_ARENTIUS_ARENTIA','Arentius and Arentia','Iberian/Lusitanian','Deity','Deity','paired divine couple; territorial/tribal protection','B','A male-female divine pair attested in the Lusitanian region of Egitania and adjacent Extremadura, often invoked with toponymic epithets.'),
 ('ENT_IB_QUANGEIUS','Quangeius','Iberian/Lusitanian','Deity','Deity','local tutelary deity; tribal protection','B','Local tutelary deity attested by Latin votive inscriptions from the Lusitanian Egitania/Beira region.'),
 ('ENT_IB_VESTIUS_ALONIECUS','Vestius Aloniecus','Iberian/Lusitanian','Deity','Deity','local tutelary deity; animal sacrifice','B','Indigenous Callaecian tutelary deity attested at Lourizán (Pontevedra) receiving animal offerings; Aloniecus likely a toponymic epithet.'),
 ('ENT_MYC_POTNIA_LABYRINTH','Mistress of the Labyrinth','Mycenaean','Mistress/Potnia','Goddess','labyrinth; sanctuary mistress; honey offering; Cretan cult','A','da-pu2-ri-to-jo po-ti-ni-ja (''Mistress of the Labyrinth'') receives honey in Linear B tablet KN Gg 702 — the earliest textual attestation of the labyrinth, a distinct Cretan Potnia.'),
 ('ENT_MYC_DRIMIOS','Drimios','Mycenaean','Deity','Deity','son of Zeus; minor Pylian deity','A','di-ri-mi-jo on Linear B tablet PY Tn 316, explicitly called di-wo i-je-we (''son of Zeus''); a distinct Mycenaean deity with no surviving Olympian identity.'),
 ('ENT_MYC_QERASIJA','Qe-ra-si-ja','Mycenaean','Deity','Deity','Knossian cult recipient; theriomorphic/Cretan','B','qe-ra-si-ja (masc. qe-ra-si-jo) receives offerings on Knossos tablets; read as ''the Theran goddess'' or a beast-cult deity, a distinct Cretan-Mycenaean name.'),
 ('ENT_MYC_PIPITUNA','Pipituna','Mycenaean','Goddess','Goddess','Cretan goddess; offering recipient','B','pi-pi-tu-na, a goddess receiving offerings on Knossos tablets (KN Fp series); a pre-Greek/Minoan-substrate theonym with no Olympian identity.'),
 ('ENT_MYC_DOPOTA','Dopota','Mycenaean','Deity','Deity','''the Lord''; sanctuary cult recipient','B','do-po-ta (probably ''Despotes / the Lord'', masculine counterpart to Potnia) receives offerings on Pylos tablets; a distinct titular deity.'),
 ('ENT_MYC_TRISHEROS','Trisheros','Mycenaean','Hero-god','Hero-god','thrice-hero; ancestor/hero cult; chthonic offering','A','ti-ri-se-ro-e (Tris-heros, ''the Thrice-Hero'') receives offerings on PY Tn 316, the earliest attestation of Mycenaean hero/ancestor cult.'),
 ('ENT_MYC_IPHIMEDEIA','Iphimedeia','Mycenaean','Goddess','Goddess','Pylian goddess; cult recipient','B','i-pi-me-de-ja on PY Tn 316; though later myth knows Iphimedeia as a mortal heroine, in the Pylos tablet she is a divine cult-recipient.'),
 ('ENT_THRA_HEROS','Thracian Horseman (Heros)','Thracian','Equestrian god','Hero-god','horseman; hunting; healing; tomb/heroic protection; chthonic','A','The most widespread Thracian divine figure, attested by hundreds of votive and funerary rider-reliefs across Thrace and Moesia, associated with hunting, healing and heroic/chthonic protection.'),
 ('ENT_THRA_PLEISTOROS','Pleistoros','Thracian','War deity','War Deity','war; human sacrifice; tribal war-cult','B','War-god of the Thracian Apsinthii recorded by Herodotus (9.119), to whom they sacrificed the Persian Oeobazus.'),
 ('ENT_THRA_ZIBELTHIURDOS','Zibelthiurdos','Thracian','Storm deity','Sky Deity','storm; thunder; lightning; sky','B','Thracian storm/sky god attested in Greek and Latin inscriptions of the Roman period, equated with Zeus/Jupiter as a thunder deity.'),
 ('ENT_THRA_KANDAON','Kandaon','Thracian','War deity','War Deity','war; battle','C','A Thracian/Macedonian war-god identified with Ares in late Greek sources (Lycophron''s Alexandra and scholia); attestation literary rather than epigraphic.'),
 ('ENT_MER_ARITENE','Aritene','Meroitic','Sun deity','Indigenous Meroitic deity','sun; solar kingship; light','B','Indigenous Meroitic god named on a faience medallion from the royal cemetery of Meroe (read by Priese as a solar deity) and in the Karanog mortuary inscription (REM 0277).'),
 ('ENT_MER_MASH','Mash','Meroitic','Local deity','Indigenous Meroitic deity','tutelary; local cult','C','Obscure indigenous Meroitic god named alongside Aritene in the Karanog mortuary inscription of Haramadeye; character otherwise unknown.'),
 ('ENT_ELAM_NAPIR','Napir','Elamite','God','Astral deity','moon; night sky; protection of the gods','A','Elamite moon god (''the shining one''), theophoric in Untash-Napirisha; titled ''protector of the gods'', invoked in the Neo-Elamite inscription of Hanni of Ayapir (EKI 75) and attested at Susa.'),
 ('ENT_ELAM_TIRUTUR','Tirutur','Elamite','God','Deity','divine royal protection (kitin); sovereignty','B','Elamite god regularly paired with Tepti in Neo-Elamite royal inscriptions; in the Hanni of Ayapir text the kitin of Tepti and Tirutur is invoked with Napir, Simut and Humban.'),
 ('ENT_ELAM_SUHSIPA','Suhsipa','Elamite','Underworld deity','Deity','funerary cult; netherworld (husa)','B','Elamite deity with a temple at Dur-Untash (Tchoga Zanbil) alongside Lagamar and Napirisha; grouped by Henkelman among gods of the husa, a funerary/netherworld sphere.');
INSERT INTO entities (entity_id,canonical_name,tradition,entity_type,category,primary_domains,cult_scope,evidence_confidence,review_status,inclusion_basis,earth_association_score,chthonic_flag,serpent_flag,short_note)
INSERT INTO _s VALUES
 ('ENT_NAB_PANTHEON','SRC_HEALEY_NABATAEAN_RELIGION','Collective grouping the deities worshipped across the Nabataean kingdom from Petra and Bostra to Hegra (Madaʾin Salih), attested in Nabataean Aramaic inscriptions and rock-cut sanctuaries.','scholarly attestation'),
 ('ENT_NAB_SHAI_AL_QAUM','SRC_HEALEY_NABATAEAN_RELIGION','Caravan-protector and warrior god ''who drinks no wine and builds no tomb,'' named in a bilingual Nabataean altar from Palmyra (CIS II 3978).','scholarly attestation'),
 ('ENT_NAB_ARA','SRC_HEALEY_NABATAEAN_RELIGION','Tutelary god of Bostra closely associated with Dushara, who is titled ''the god of our lord who is in Bostra'' in Nabataean Hawran inscriptions.','scholarly attestation'),
 ('ENT_NAB_AL_KUTBA','SRC_HEALEY_NABATAEAN_RELIGION','Scribal and commerce deity (Nabataean counterpart of Babylonian Nabu / Greek Hermes), attested at Petra, Hegra and Sinai; sometimes the goddess al-Kutbay.','scholarly attestation'),
 ('ENT_NAB_MANOTU','SRC_HEALEY_NABATAEAN_RELIGION','Hegran cult-form of the fate-goddess Manat, invoked as ''Manotu and her Qaisha'' in the tomb-curse inscriptions of Hegra to protect burials.','scholarly attestation'),
 ('ENT_NAB_AL_UZZA_PETRA','SRC_HEALEY_NABATAEAN_RELIGION','Petraean cult-form of al-ʿUzza, chief Nabataean goddess identified with Aphrodite, associated with Petra''s Temple of the Winged Lions.','scholarly attestation'),
 ('ENT_ARAB_KAABA_IDOLS','SRC_QURAN','Collective of the betyls and idols of the Hijaz and wider Arabia catalogued in Ibn al-Kalbi''s Kitab al-Asnam and reflected in Qurʾan 71:23.','direct attestation'),
 ('ENT_ARAB_ISAF','SRC_HOYLAND_ARABIA','Idol at the Kaʿba; in tradition a man petrified for sacrilege, paired with Nāʾila, attested in Ibn al-Kalbi at al-Safa/al-Marwa.','scholarly attestation'),
 ('ENT_ARAB_NAILA','SRC_HOYLAND_ARABIA','Female idol at the Kaʿba, paired with Isāf as a petrified couple, attested in Ibn al-Kalbi at al-Safa/al-Marwa.','scholarly attestation'),
 ('ENT_ARAB_MANAF','SRC_HOYLAND_ARABIA','Meccan deity whose name survives in the Quraysh name ʿAbd Manaf; listed among the gods of Mecca in Ibn al-Kalbi.','scholarly attestation'),
 ('ENT_ARAB_DHUL_KHALASA','SRC_HOYLAND_ARABIA','White quartz betyl and oracular sanctuary at Tabala in Yemen, ''the Yemeni Kaʿba,'' venerated by Daws, Khathʿam and Bajila per Ibn al-Kalbi.','scholarly attestation'),
 ('ENT_ARAB_RUDA','SRC_HOYLAND_ARABIA','North Arabian astral deity (Venus) attested in Thamudic and Safaitic inscriptions and named in Assyrian records as ''Ruldaiu''; also in Ibn al-Kalbi.','scholarly attestation'),
 ('ENT_ARAB_NUHM','SRC_HOYLAND_ARABIA','Deity of the Muzayna tribe whose name survives in the theophoric ʿAbd Nuhm; listed in Ibn al-Kalbi.','scholarly attestation'),
 ('ENT_ARAB_AL_FALS','SRC_HOYLAND_ARABIA','Idol of the Tayyiʾ tribe, a reddish rock outcrop on Jabal Aja serving as a place of asylum, described in Ibn al-Kalbi.','scholarly attestation'),
 ('ENT_ARAB_SAD','SRC_HOYLAND_ARABIA','A tall rock idol of the Banu Milkan (Kinana) on which sacrificial blood was poured, attested in Ibn al-Kalbi.','scholarly attestation'),
 ('ENT_ARAB_QUZAH','SRC_HOYLAND_ARABIA','Storm/rainbow deity associated with the hill Quzaḥ at Muzdalifa near Mecca; Arabic qaws Quzaḥ (''Quzaḥ''s bow'' = rainbow) preserves his name.','scholarly attestation'),
 ('ENT_ARAB_SUWA','SRC_QURAN','One of the five antediluvian idols of Qurʾan 71:23; later the idol of the Hudhayl tribe at Ruhat per Ibn al-Kalbi.','direct attestation'),
 ('ENT_ARAB_YAUQ','SRC_QURAN','One of the five antediluvian idols of Qurʾan 71:23 (''the preventer/protector''); horse-formed idol of Hamdan at Khaywan in Yemen per Ibn al-Kalbi.','direct attestation'),
 ('ENT_SAB_WADD','SRC_QURAN','National god of the Minaean (Maʿin) kingdom and a moon-deity; the formula ''Wd ʾb'' (Wadd is father) is widely attested on amulets and inscriptions; one of the five idols of Qurʾan 71:23.','direct attestation'),
 ('ENT_SAB_ANBAY','SRC_HOYLAND_ARABIA','Qatabanian oracular and law-giving god, paired with Ḥawkam; ''Anbay and Ḥawkam'' issue decrees in Qatabanian legal inscriptions.','scholarly attestation'),
 ('ENT_SAB_SAYIN','SRC_HOYLAND_ARABIA','National god of the kingdom of Hadramawt, attested in royal dedications and the great temple at Shabwa; a solar/national patron of Hadramite kingship.','scholarly attestation'),
 ('ENT_SAB_SIN_HAWL','SRC_HOYLAND_ARABIA','Moon-god of Hadramawt bearing the epithet Hawl, attested at Shabwa; distinct from the Mesopotamian Sin though sharing the lunar name.','scholarly attestation'),
 ('ENT_SAB_TALAB','SRC_HOYLAND_ARABIA','Tutelary god of the Sabaean tribe Banu Sumʿay, titled ''Taʾlab Riyam'' after his sanctuary on the Riyam massif; many oracle and pilgrimage inscriptions record his cult.','scholarly attestation'),
 ('ENT_SAB_HAWBAS','SRC_HOYLAND_ARABIA','Sabaean deity closely associated with Almaqah, frequently named alongside him at Awwam/Marib and in Dʿmt-period Ethiopia.','scholarly attestation'),
 ('ENT_SAB_DHAT_HIMYAM','SRC_HOYLAND_ARABIA','One of the two solar ''Ladies'' (Dhat = ''She of'') of the Sabaean pantheon, a hypostasis of the sun-goddess; her cult was carried to Dʿmt-period Ethiopia.','scholarly attestation'),
 ('ENT_SAB_DHAT_BADAN','SRC_HOYLAND_ARABIA','The second solar ''Lady'' of the Sabaean pantheon, paired with Dhat-Himyam; both invoked in temple dedications such as those from the Awwam sanctuary.','scholarly attestation'),
 ('ENT_SAB_DHAT_ZAHRAN','SRC_HOYLAND_ARABIA','A further solar ''Lady'' epithet of the South-Arabian sun-goddess attested in dedicatory inscriptions, a localized hypostasis of Shams.','scholarly attestation'),
 ('ENT_SAB_BASAMUM','SRC_HOYLAND_ARABIA','South-Arabian god of healing, his name connected to the balsam/aromatic plant (bsm); attested in votive cure-texts.','scholarly attestation'),
 ('ENT_SAB_NASR','SRC_QURAN','A South/West-Arabian deity (''vulture/eagle'') named in Qurʾan 71:23 and attested in onomastics; venerated in the Himyaritic/Yemeni sphere.','direct attestation'),
 ('ENT_SAB_YAGHUTH','SRC_QURAN','Pre-Islamic deity (''he helps'') named in Qurʾan 71:23 alongside Yaʿuq and Nasr; lion-idol of Madhhij/Murad in Yemen per Ibn al-Kalbi.','direct attestation'),
 ('ENT_AKS_PANTHEON','SRC_MUNRO_HAY_AKSUM','The pagan deities worshipped in the Dʿmt kingdom and pre-Christian Aksum, attested in the pre-monotheist inscriptions of King Ezana and in Dʿmt-period South-Arabian-derived dedications.','scholarly attestation'),
 ('ENT_AKS_MAHREM','SRC_MUNRO_HAY_AKSUM','Chief god and divine ancestor of the Aksumite kings, ''invincible to the enemy''; Ezana''s Greek inscription equates him with Ares and styles the king ''son of Mahrem''.','scholarly attestation'),
 ('ENT_AKS_ASTAR','SRC_MUNRO_HAY_AKSUM','Aksumite reflex of the South-Arabian astral god ʿAthtar (Venus), named first in Ezana''s pre-Christian triad ''Astar, Beher and Medr''.','scholarly attestation'),
 ('ENT_AKS_BEHER','SRC_MUNRO_HAY_AKSUM','Aksumite god of the sea (later ''land/country''), named in Ezana''s triad; in the Greek version the maritime deity corresponds to Poseidon.','scholarly attestation'),
 ('ENT_AKS_MEDR','SRC_MUNRO_HAY_AKSUM','Aksumite earth god (Geʿez medr = ''earth/land''), the third member of Ezana''s pre-Christian triad, aligned with the Greek earth deity.','scholarly attestation'),
 ('ENT_ARA_BEL_PALMYRA','SRC_TEIXIDOR_PALMYRA','Head of the Palmyrene pantheon, worshipped in the great Temple of Bel (dedicated 32 CE); a Bel form assimilated to Babylonian Bel-Marduk, heading the astral triad with Yarhibol and Aglibol.','scholarly attestation'),
 ('ENT_ARA_YARHIBOL','SRC_TEIXIDOR_PALMYRA','Palmyrene solar god, originally guardian of the sacred spring Efqa, depicted with a radiate nimbus and flanking Bel in the Temple of Bel.','scholarly attestation'),
 ('ENT_ARA_AGLIBOL','SRC_TEIXIDOR_PALMYRA','Palmyrene lunar god depicted with a crescent, paired with Malakbel in the Sacred Garden cult and flanking Bel in the Temple of Bel.','scholarly attestation'),
 ('ENT_ARA_MALAKBEL','SRC_TEIXIDOR_PALMYRA','Palmyrene solar and vegetation god (''Messenger of Bel''), paired with Aglibol; the bilingual altar in Rome equates him with Sol Sanctissimus.','scholarly attestation'),
 ('ENT_ARA_ALLAT_PALMYRA','SRC_TEIXIDOR_PALMYRA','Arab goddess worshipped at Palmyra in her own sanctuary, assimilated to armed Athena, attested in Palmyrene and bilingual dedications.','scholarly attestation'),
 ('ENT_ARA_SIN_HARRAN','SRC_LIPINSKI_ARAMEANS','The moon god of the Ehulhul sanctuary at Harran, the principal lunar cult of the Aramean/Assyrian north; named in the Sefire treaty curses and rebuilt by Nabonidus.','scholarly attestation'),
 ('ENT_ARA_RAKIB_EL','SRC_LIPINSKI_ARAMEANS','''Charioteer of El'', tutelary dynastic god of the kings of Samʾal/Zincirli, named in the 8th-c. BCE Hadad, Panamuwa and Kilamuwa inscriptions.','scholarly attestation'),
 ('ENT_ARA_SAHAR','SRC_LIPINSKI_ARAMEANS','Aramean moon deity (Aramaic shr, ''crescent'') invoked among the gods of the royal house at Samʾal in the Panamuwa inscriptions of Zincirli.','scholarly attestation'),
 ('ENT_ARA_KUBABA','SRC_LIPINSKI_ARAMEANS','Tutelary goddess of Carchemish, a leading deity of the Syro-Hittite/Aramean north in Luwian and Aramaic inscriptions; later underlies Anatolian Kybele.','scholarly attestation'),
 ('ENT_ARA_ELAGABAL','SRC_LIPINSKI_ARAMEANS','The sun god of Emesa (''Ila gabal, god of the mountain'') worshipped as a conical black betyl; his priest-emperor Elagabalus installed the stone in Rome, attested on coinage and by Herodian.','scholarly attestation'),
 ('ENT_ARA_AZIZOS','SRC_LIPINSKI_ARAMEANS','The morning-star deity of Edessa, paired with Monimos as the two attendants of the sun; identified with Venus/Phosphoros by Julian (Hymn to King Helios).','scholarly attestation'),
 ('ENT_ARA_MONIMOS','SRC_LIPINSKI_ARAMEANS','The evening-star deity of Edessa (Aramaic mnʿm, ''the favourable one''), twin attendant of the sun alongside Azizos, named by Julian (Hymn to King Helios).','scholarly attestation'),
 ('ENT_URA_TRIAD','SRC_PIOTROVSKY_URARTU','The organizing triad of the Urartian state pantheon — Khaldi (supreme/war), Teisheba (storm), Shivini (sun) — opening the 79-deity Meher Kapisi god-list of Ishpuini and Minua.','scholarly attestation'),
 ('ENT_URA_BAGMASHTU','SRC_PIOTROVSKY_URARTU','Consort of Khaldi at Musasir (Ardini); where most of Urartu names Arubani as Khaldi''s wife, Musasir dedications name ''Khaldi and his wife Bagmashtu'', a regional consort tradition.','scholarly attestation'),
 ('ENT_URA_SELARDI','SRC_PIOTROVSKY_URARTU','Urartian moon deity named in the Meher Kapisi god-list; gender and full role debated, attestation limited to the divine list.','scholarly attestation'),
 ('ENT_URA_TUSHPUEA','SRC_PIOTROVSKY_URARTU','Urartian goddess listed third in the female-deity sequence of the Meher Kapisi inscription (paralleling Shivini); the capital Tushpa is held to derive its name from her.','scholarly attestation'),
 ('ENT_URA_HUBA','SRC_PIOTROVSKY_URARTU','Consort of the storm-god Teisheba in the Urartian god-list, corresponding to Hurrian Hepat, consort of Teshub, consistent with Teisheba being the Urartian reception of Teshub.','scholarly attestation'),
 ('ENT_URA_SARDI','SRC_PIOTROVSKY_URARTU','Urartian astral/star deity named in the Meher Kapisi god-list, identified by a single domain and a sacrifice allotment with no surviving narrative.','scholarly attestation'),
 ('ENT_URA_SPEAR_KHALDI','SRC_PIOTROVSKY_URARTU','The lance of Khaldi was a sacred weapon embodying the war-god''s power; the Karagunduz stele praises it as victorious, and Khaldi''s temples were ''houses of weapons''.','scholarly attestation'),
 ('ENT_IB_COSUS','SRC_OLIVARES_IBERIAN','War-god attested by ~20 Latin votive inscriptions in Galicia and northern Portugal, interpreted via interpretatio romana as a Mars-type god of the Callaeci; sometimes identified with Cariociecus.','scholarly attestation'),
 ('ENT_IB_REUE','SRC_OLIVARES_IBERIAN','Supreme/sky deity (from IE *dyeu-) in Lusitanian ritual texts including the Cabeço das Fraguas inscription and Arronches plaque, with epithets Reve Anabaraego and Reve Larauco.','scholarly attestation'),
 ('ENT_IB_RUNESOCESIUS','SRC_OLIVARES_IBERIAN','War/javelin god attested at the São Miguel da Mota / Alentejo cult region, connected to the Endovelicus sanctuary complex.','scholarly attestation'),
 ('ENT_IB_BORMANICUS','SRC_OLIVARES_IBERIAN','Thermal-spring/healing-waters god attested at the hot-spring sanctuary of Caldas de Vizela; of the Celtic Bormo/Borvo family of spring deities.','scholarly attestation'),
 ('ENT_IB_TONGOENABIAGUS','SRC_OLIVARES_IBERIAN','Spring deity attested at a sacred spring beside the river Cávado at Braga; the -nabiagus element links it to the Nabia water-deity family.','scholarly attestation'),
 ('ENT_IB_ARENTIUS_ARENTIA','SRC_OLIVARES_IBERIAN','A male-female divine pair attested in the Lusitanian region of Egitania and adjacent Extremadura, often invoked with toponymic epithets.','scholarly attestation'),
 ('ENT_IB_QUANGEIUS','SRC_OLIVARES_IBERIAN','Local tutelary deity attested by Latin votive inscriptions from the Lusitanian Egitania/Beira region.','scholarly attestation'),
 ('ENT_IB_VESTIUS_ALONIECUS','SRC_OLIVARES_IBERIAN','Indigenous Callaecian tutelary deity attested at Lourizán (Pontevedra) receiving animal offerings; Aloniecus likely a toponymic epithet.','scholarly attestation'),
 ('ENT_MYC_POTNIA_LABYRINTH','SRC_VENTRIS_CHADWICK','da-pu2-ri-to-jo po-ti-ni-ja (''Mistress of the Labyrinth'') receives honey in Linear B tablet KN Gg 702 — the earliest textual attestation of the labyrinth, a distinct Cretan Potnia.','scholarly attestation'),
 ('ENT_MYC_DRIMIOS','SRC_VENTRIS_CHADWICK','di-ri-mi-jo on Linear B tablet PY Tn 316, explicitly called di-wo i-je-we (''son of Zeus''); a distinct Mycenaean deity with no surviving Olympian identity.','scholarly attestation'),
 ('ENT_MYC_QERASIJA','SRC_VENTRIS_CHADWICK','qe-ra-si-ja (masc. qe-ra-si-jo) receives offerings on Knossos tablets; read as ''the Theran goddess'' or a beast-cult deity, a distinct Cretan-Mycenaean name.','scholarly attestation'),
 ('ENT_MYC_PIPITUNA','SRC_VENTRIS_CHADWICK','pi-pi-tu-na, a goddess receiving offerings on Knossos tablets (KN Fp series); a pre-Greek/Minoan-substrate theonym with no Olympian identity.','scholarly attestation'),
 ('ENT_MYC_DOPOTA','SRC_VENTRIS_CHADWICK','do-po-ta (probably ''Despotes / the Lord'', masculine counterpart to Potnia) receives offerings on Pylos tablets; a distinct titular deity.','scholarly attestation'),
 ('ENT_MYC_TRISHEROS','SRC_VENTRIS_CHADWICK','ti-ri-se-ro-e (Tris-heros, ''the Thrice-Hero'') receives offerings on PY Tn 316, the earliest attestation of Mycenaean hero/ancestor cult.','scholarly attestation'),
 ('ENT_MYC_IPHIMEDEIA','SRC_VENTRIS_CHADWICK','i-pi-me-de-ja on PY Tn 316; though later myth knows Iphimedeia as a mortal heroine, in the Pylos tablet she is a divine cult-recipient.','scholarly attestation'),
 ('ENT_THRA_HEROS','SRC_HODDINOTT_THRACIANS','The most widespread Thracian divine figure, attested by hundreds of votive and funerary rider-reliefs across Thrace and Moesia, associated with hunting, healing and heroic/chthonic protection.','scholarly attestation'),
 ('ENT_THRA_PLEISTOROS','SRC_HODDINOTT_THRACIANS','War-god of the Thracian Apsinthii recorded by Herodotus (9.119), to whom they sacrificed the Persian Oeobazus.','scholarly attestation'),
 ('ENT_THRA_ZIBELTHIURDOS','SRC_HODDINOTT_THRACIANS','Thracian storm/sky god attested in Greek and Latin inscriptions of the Roman period, equated with Zeus/Jupiter as a thunder deity.','scholarly attestation'),
 ('ENT_THRA_KANDAON','SRC_HODDINOTT_THRACIANS','A Thracian/Macedonian war-god identified with Ares in late Greek sources (Lycophron''s Alexandra and scholia); attestation literary rather than epigraphic.','scholarly attestation'),
 ('ENT_MER_ARITENE','SRC_TÖRÖK_MEROE','Indigenous Meroitic god named on a faience medallion from the royal cemetery of Meroe (read by Priese as a solar deity) and in the Karanog mortuary inscription (REM 0277).','scholarly attestation'),
 ('ENT_MER_MASH','SRC_TÖRÖK_MEROE','Obscure indigenous Meroitic god named alongside Aritene in the Karanog mortuary inscription of Haramadeye; character otherwise unknown.','scholarly attestation'),
 ('ENT_ELAM_NAPIR','SRC_POTTS_ELAM','Elamite moon god (''the shining one''), theophoric in Untash-Napirisha; titled ''protector of the gods'', invoked in the Neo-Elamite inscription of Hanni of Ayapir (EKI 75) and attested at Susa.','scholarly attestation'),
 ('ENT_ELAM_TIRUTUR','SRC_POTTS_ELAM','Elamite god regularly paired with Tepti in Neo-Elamite royal inscriptions; in the Hanni of Ayapir text the kitin of Tepti and Tirutur is invoked with Napir, Simut and Humban.','scholarly attestation'),
 ('ENT_ELAM_SUHSIPA','SRC_HENKELMAN_ELAM','Elamite deity with a temple at Dur-Untash (Tchoga Zanbil) alongside Lagamar and Napirisha; grouped by Henkelman among gods of the husa, a funerary/netherworld sphere.','scholarly attestation');
INSERT INTO entity_sources (entity_id,source_id,evidence_type,source_note)
INSERT INTO _p VALUES
 ('ENT_NAB_PANTHEON','PER_NABATAEAN','Collective grouping the deities worshipped across the Nabataean kingdom from Petra and Bostra to Hegra (Madaʾin Salih), attested in Nabataean Aramaic inscriptions and rock-cut sanctuaries.'),
 ('ENT_NAB_SHAI_AL_QAUM','PER_NABATAEAN','Caravan-protector and warrior god ''who drinks no wine and builds no tomb,'' named in a bilingual Nabataean altar from Palmyra (CIS II 3978).'),
 ('ENT_NAB_ARA','PER_NABATAEAN','Tutelary god of Bostra closely associated with Dushara, who is titled ''the god of our lord who is in Bostra'' in Nabataean Hawran inscriptions.'),
 ('ENT_NAB_AL_KUTBA','PER_NABATAEAN','Scribal and commerce deity (Nabataean counterpart of Babylonian Nabu / Greek Hermes), attested at Petra, Hegra and Sinai; sometimes the goddess al-Kutbay.'),
 ('ENT_NAB_MANOTU','PER_NABATAEAN','Hegran cult-form of the fate-goddess Manat, invoked as ''Manotu and her Qaisha'' in the tomb-curse inscriptions of Hegra to protect burials.'),
 ('ENT_NAB_AL_UZZA_PETRA','PER_NABATAEAN','Petraean cult-form of al-ʿUzza, chief Nabataean goddess identified with Aphrodite, associated with Petra''s Temple of the Winged Lions.'),
 ('ENT_ARAB_KAABA_IDOLS','PER_ARA_PRE_ISLAMIC','Collective of the betyls and idols of the Hijaz and wider Arabia catalogued in Ibn al-Kalbi''s Kitab al-Asnam and reflected in Qurʾan 71:23.'),
 ('ENT_ARAB_ISAF','PER_ARA_PRE_ISLAMIC','Idol at the Kaʿba; in tradition a man petrified for sacrilege, paired with Nāʾila, attested in Ibn al-Kalbi at al-Safa/al-Marwa.'),
 ('ENT_ARAB_NAILA','PER_ARA_PRE_ISLAMIC','Female idol at the Kaʿba, paired with Isāf as a petrified couple, attested in Ibn al-Kalbi at al-Safa/al-Marwa.'),
 ('ENT_ARAB_MANAF','PER_ARA_PRE_ISLAMIC','Meccan deity whose name survives in the Quraysh name ʿAbd Manaf; listed among the gods of Mecca in Ibn al-Kalbi.'),
 ('ENT_ARAB_DHUL_KHALASA','PER_ARA_PRE_ISLAMIC','White quartz betyl and oracular sanctuary at Tabala in Yemen, ''the Yemeni Kaʿba,'' venerated by Daws, Khathʿam and Bajila per Ibn al-Kalbi.'),
 ('ENT_ARAB_RUDA','PER_ARA_PRE_ISLAMIC','North Arabian astral deity (Venus) attested in Thamudic and Safaitic inscriptions and named in Assyrian records as ''Ruldaiu''; also in Ibn al-Kalbi.'),
 ('ENT_ARAB_NUHM','PER_ARA_PRE_ISLAMIC','Deity of the Muzayna tribe whose name survives in the theophoric ʿAbd Nuhm; listed in Ibn al-Kalbi.'),
 ('ENT_ARAB_AL_FALS','PER_ARA_PRE_ISLAMIC','Idol of the Tayyiʾ tribe, a reddish rock outcrop on Jabal Aja serving as a place of asylum, described in Ibn al-Kalbi.'),
 ('ENT_ARAB_SAD','PER_ARA_PRE_ISLAMIC','A tall rock idol of the Banu Milkan (Kinana) on which sacrificial blood was poured, attested in Ibn al-Kalbi.'),
 ('ENT_ARAB_QUZAH','PER_ARA_PRE_ISLAMIC','Storm/rainbow deity associated with the hill Quzaḥ at Muzdalifa near Mecca; Arabic qaws Quzaḥ (''Quzaḥ''s bow'' = rainbow) preserves his name.'),
 ('ENT_ARAB_SUWA','PER_ARA_PRE_ISLAMIC','One of the five antediluvian idols of Qurʾan 71:23; later the idol of the Hudhayl tribe at Ruhat per Ibn al-Kalbi.'),
 ('ENT_ARAB_YAUQ','PER_ARA_PRE_ISLAMIC','One of the five antediluvian idols of Qurʾan 71:23 (''the preventer/protector''); horse-formed idol of Hamdan at Khaywan in Yemen per Ibn al-Kalbi.'),
 ('ENT_SAB_WADD','PER_SABAEAN','National god of the Minaean (Maʿin) kingdom and a moon-deity; the formula ''Wd ʾb'' (Wadd is father) is widely attested on amulets and inscriptions; one of the five idols of Qurʾan 71:23.'),
 ('ENT_SAB_ANBAY','PER_SABAEAN','Qatabanian oracular and law-giving god, paired with Ḥawkam; ''Anbay and Ḥawkam'' issue decrees in Qatabanian legal inscriptions.'),
 ('ENT_SAB_SAYIN','PER_SABAEAN','National god of the kingdom of Hadramawt, attested in royal dedications and the great temple at Shabwa; a solar/national patron of Hadramite kingship.'),
 ('ENT_SAB_SIN_HAWL','PER_SABAEAN','Moon-god of Hadramawt bearing the epithet Hawl, attested at Shabwa; distinct from the Mesopotamian Sin though sharing the lunar name.'),
 ('ENT_SAB_TALAB','PER_SABAEAN','Tutelary god of the Sabaean tribe Banu Sumʿay, titled ''Taʾlab Riyam'' after his sanctuary on the Riyam massif; many oracle and pilgrimage inscriptions record his cult.'),
 ('ENT_SAB_HAWBAS','PER_SABAEAN','Sabaean deity closely associated with Almaqah, frequently named alongside him at Awwam/Marib and in Dʿmt-period Ethiopia.'),
 ('ENT_SAB_DHAT_HIMYAM','PER_SABAEAN','One of the two solar ''Ladies'' (Dhat = ''She of'') of the Sabaean pantheon, a hypostasis of the sun-goddess; her cult was carried to Dʿmt-period Ethiopia.'),
 ('ENT_SAB_DHAT_BADAN','PER_SABAEAN','The second solar ''Lady'' of the Sabaean pantheon, paired with Dhat-Himyam; both invoked in temple dedications such as those from the Awwam sanctuary.'),
 ('ENT_SAB_DHAT_ZAHRAN','PER_SABAEAN','A further solar ''Lady'' epithet of the South-Arabian sun-goddess attested in dedicatory inscriptions, a localized hypostasis of Shams.'),
 ('ENT_SAB_BASAMUM','PER_SABAEAN','South-Arabian god of healing, his name connected to the balsam/aromatic plant (bsm); attested in votive cure-texts.'),
 ('ENT_SAB_NASR','PER_SABAEAN','A South/West-Arabian deity (''vulture/eagle'') named in Qurʾan 71:23 and attested in onomastics; venerated in the Himyaritic/Yemeni sphere.'),
 ('ENT_SAB_YAGHUTH','PER_SABAEAN','Pre-Islamic deity (''he helps'') named in Qurʾan 71:23 alongside Yaʿuq and Nasr; lion-idol of Madhhij/Murad in Yemen per Ibn al-Kalbi.'),
 ('ENT_AKS_PANTHEON','PER_DMT_AKSUM','The pagan deities worshipped in the Dʿmt kingdom and pre-Christian Aksum, attested in the pre-monotheist inscriptions of King Ezana and in Dʿmt-period South-Arabian-derived dedications.'),
 ('ENT_AKS_MAHREM','PER_DMT_AKSUM','Chief god and divine ancestor of the Aksumite kings, ''invincible to the enemy''; Ezana''s Greek inscription equates him with Ares and styles the king ''son of Mahrem''.'),
 ('ENT_AKS_ASTAR','PER_DMT_AKSUM','Aksumite reflex of the South-Arabian astral god ʿAthtar (Venus), named first in Ezana''s pre-Christian triad ''Astar, Beher and Medr''.'),
 ('ENT_AKS_BEHER','PER_DMT_AKSUM','Aksumite god of the sea (later ''land/country''), named in Ezana''s triad; in the Greek version the maritime deity corresponds to Poseidon.'),
 ('ENT_AKS_MEDR','PER_DMT_AKSUM','Aksumite earth god (Geʿez medr = ''earth/land''), the third member of Ezana''s pre-Christian triad, aligned with the Greek earth deity.'),
 ('ENT_ARA_BEL_PALMYRA','PER_ARA_IRON_AGE','Head of the Palmyrene pantheon, worshipped in the great Temple of Bel (dedicated 32 CE); a Bel form assimilated to Babylonian Bel-Marduk, heading the astral triad with Yarhibol and Aglibol.'),
 ('ENT_ARA_YARHIBOL','PER_ARA_IRON_AGE','Palmyrene solar god, originally guardian of the sacred spring Efqa, depicted with a radiate nimbus and flanking Bel in the Temple of Bel.'),
 ('ENT_ARA_AGLIBOL','PER_ARA_IRON_AGE','Palmyrene lunar god depicted with a crescent, paired with Malakbel in the Sacred Garden cult and flanking Bel in the Temple of Bel.'),
 ('ENT_ARA_MALAKBEL','PER_ARA_IRON_AGE','Palmyrene solar and vegetation god (''Messenger of Bel''), paired with Aglibol; the bilingual altar in Rome equates him with Sol Sanctissimus.'),
 ('ENT_ARA_ALLAT_PALMYRA','PER_ARA_IRON_AGE','Arab goddess worshipped at Palmyra in her own sanctuary, assimilated to armed Athena, attested in Palmyrene and bilingual dedications.'),
 ('ENT_ARA_SIN_HARRAN','PER_ARA_IRON_AGE','The moon god of the Ehulhul sanctuary at Harran, the principal lunar cult of the Aramean/Assyrian north; named in the Sefire treaty curses and rebuilt by Nabonidus.'),
 ('ENT_ARA_RAKIB_EL','PER_ARA_IRON_AGE','''Charioteer of El'', tutelary dynastic god of the kings of Samʾal/Zincirli, named in the 8th-c. BCE Hadad, Panamuwa and Kilamuwa inscriptions.'),
 ('ENT_ARA_SAHAR','PER_ARA_IRON_AGE','Aramean moon deity (Aramaic shr, ''crescent'') invoked among the gods of the royal house at Samʾal in the Panamuwa inscriptions of Zincirli.'),
 ('ENT_ARA_KUBABA','PER_ARA_IRON_AGE','Tutelary goddess of Carchemish, a leading deity of the Syro-Hittite/Aramean north in Luwian and Aramaic inscriptions; later underlies Anatolian Kybele.'),
 ('ENT_ARA_ELAGABAL','PER_ARA_IRON_AGE','The sun god of Emesa (''Ila gabal, god of the mountain'') worshipped as a conical black betyl; his priest-emperor Elagabalus installed the stone in Rome, attested on coinage and by Herodian.'),
 ('ENT_ARA_AZIZOS','PER_ARA_IRON_AGE','The morning-star deity of Edessa, paired with Monimos as the two attendants of the sun; identified with Venus/Phosphoros by Julian (Hymn to King Helios).'),
 ('ENT_ARA_MONIMOS','PER_ARA_IRON_AGE','The evening-star deity of Edessa (Aramaic mnʿm, ''the favourable one''), twin attendant of the sun alongside Azizos, named by Julian (Hymn to King Helios).'),
 ('ENT_URA_TRIAD','PER_URA_IRON_AGE','The organizing triad of the Urartian state pantheon — Khaldi (supreme/war), Teisheba (storm), Shivini (sun) — opening the 79-deity Meher Kapisi god-list of Ishpuini and Minua.'),
 ('ENT_URA_BAGMASHTU','PER_URA_IRON_AGE','Consort of Khaldi at Musasir (Ardini); where most of Urartu names Arubani as Khaldi''s wife, Musasir dedications name ''Khaldi and his wife Bagmashtu'', a regional consort tradition.'),
 ('ENT_URA_SELARDI','PER_URA_IRON_AGE','Urartian moon deity named in the Meher Kapisi god-list; gender and full role debated, attestation limited to the divine list.'),
 ('ENT_URA_TUSHPUEA','PER_URA_IRON_AGE','Urartian goddess listed third in the female-deity sequence of the Meher Kapisi inscription (paralleling Shivini); the capital Tushpa is held to derive its name from her.'),
 ('ENT_URA_HUBA','PER_URA_IRON_AGE','Consort of the storm-god Teisheba in the Urartian god-list, corresponding to Hurrian Hepat, consort of Teshub, consistent with Teisheba being the Urartian reception of Teshub.'),
 ('ENT_URA_SARDI','PER_URA_IRON_AGE','Urartian astral/star deity named in the Meher Kapisi god-list, identified by a single domain and a sacrifice allotment with no surviving narrative.'),
 ('ENT_URA_SPEAR_KHALDI','PER_URA_IRON_AGE','The lance of Khaldi was a sacred weapon embodying the war-god''s power; the Karagunduz stele praises it as victorious, and Khaldi''s temples were ''houses of weapons''.'),
 ('ENT_IB_COSUS','PER_IB_IRON_AGE','War-god attested by ~20 Latin votive inscriptions in Galicia and northern Portugal, interpreted via interpretatio romana as a Mars-type god of the Callaeci; sometimes identified with Cariociecus.'),
 ('ENT_IB_REUE','PER_IB_IRON_AGE','Supreme/sky deity (from IE *dyeu-) in Lusitanian ritual texts including the Cabeço das Fraguas inscription and Arronches plaque, with epithets Reve Anabaraego and Reve Larauco.'),
 ('ENT_IB_RUNESOCESIUS','PER_IB_IRON_AGE','War/javelin god attested at the São Miguel da Mota / Alentejo cult region, connected to the Endovelicus sanctuary complex.'),
 ('ENT_IB_BORMANICUS','PER_IB_IRON_AGE','Thermal-spring/healing-waters god attested at the hot-spring sanctuary of Caldas de Vizela; of the Celtic Bormo/Borvo family of spring deities.'),
 ('ENT_IB_TONGOENABIAGUS','PER_IB_IRON_AGE','Spring deity attested at a sacred spring beside the river Cávado at Braga; the -nabiagus element links it to the Nabia water-deity family.'),
 ('ENT_IB_ARENTIUS_ARENTIA','PER_IB_IRON_AGE','A male-female divine pair attested in the Lusitanian region of Egitania and adjacent Extremadura, often invoked with toponymic epithets.'),
 ('ENT_IB_QUANGEIUS','PER_IB_IRON_AGE','Local tutelary deity attested by Latin votive inscriptions from the Lusitanian Egitania/Beira region.'),
 ('ENT_IB_VESTIUS_ALONIECUS','PER_IB_IRON_AGE','Indigenous Callaecian tutelary deity attested at Lourizán (Pontevedra) receiving animal offerings; Aloniecus likely a toponymic epithet.'),
 ('ENT_MYC_POTNIA_LABYRINTH','PER_GRK_MYCENAEAN','da-pu2-ri-to-jo po-ti-ni-ja (''Mistress of the Labyrinth'') receives honey in Linear B tablet KN Gg 702 — the earliest textual attestation of the labyrinth, a distinct Cretan Potnia.'),
 ('ENT_MYC_DRIMIOS','PER_GRK_MYCENAEAN','di-ri-mi-jo on Linear B tablet PY Tn 316, explicitly called di-wo i-je-we (''son of Zeus''); a distinct Mycenaean deity with no surviving Olympian identity.'),
 ('ENT_MYC_QERASIJA','PER_GRK_MYCENAEAN','qe-ra-si-ja (masc. qe-ra-si-jo) receives offerings on Knossos tablets; read as ''the Theran goddess'' or a beast-cult deity, a distinct Cretan-Mycenaean name.'),
 ('ENT_MYC_PIPITUNA','PER_GRK_MYCENAEAN','pi-pi-tu-na, a goddess receiving offerings on Knossos tablets (KN Fp series); a pre-Greek/Minoan-substrate theonym with no Olympian identity.'),
 ('ENT_MYC_DOPOTA','PER_GRK_MYCENAEAN','do-po-ta (probably ''Despotes / the Lord'', masculine counterpart to Potnia) receives offerings on Pylos tablets; a distinct titular deity.'),
 ('ENT_MYC_TRISHEROS','PER_GRK_MYCENAEAN','ti-ri-se-ro-e (Tris-heros, ''the Thrice-Hero'') receives offerings on PY Tn 316, the earliest attestation of Mycenaean hero/ancestor cult.'),
 ('ENT_MYC_IPHIMEDEIA','PER_GRK_MYCENAEAN','i-pi-me-de-ja on PY Tn 316; though later myth knows Iphimedeia as a mortal heroine, in the Pylos tablet she is a divine cult-recipient.'),
 ('ENT_THRA_HEROS','PER_THRA_IRON_AGE','The most widespread Thracian divine figure, attested by hundreds of votive and funerary rider-reliefs across Thrace and Moesia, associated with hunting, healing and heroic/chthonic protection.'),
 ('ENT_THRA_PLEISTOROS','PER_THRA_IRON_AGE','War-god of the Thracian Apsinthii recorded by Herodotus (9.119), to whom they sacrificed the Persian Oeobazus.'),
 ('ENT_THRA_ZIBELTHIURDOS','PER_THRA_IRON_AGE','Thracian storm/sky god attested in Greek and Latin inscriptions of the Roman period, equated with Zeus/Jupiter as a thunder deity.'),
 ('ENT_THRA_KANDAON','PER_THRA_IRON_AGE','A Thracian/Macedonian war-god identified with Ares in late Greek sources (Lycophron''s Alexandra and scholia); attestation literary rather than epigraphic.'),
 ('ENT_MER_ARITENE','PER_MER_NAPATAN_MEROITIC','Indigenous Meroitic god named on a faience medallion from the royal cemetery of Meroe (read by Priese as a solar deity) and in the Karanog mortuary inscription (REM 0277).'),
 ('ENT_MER_MASH','PER_MER_NAPATAN_MEROITIC','Obscure indigenous Meroitic god named alongside Aritene in the Karanog mortuary inscription of Haramadeye; character otherwise unknown.'),
 ('ENT_ELAM_NAPIR','PER_ELAM_CLASSICAL','Elamite moon god (''the shining one''), theophoric in Untash-Napirisha; titled ''protector of the gods'', invoked in the Neo-Elamite inscription of Hanni of Ayapir (EKI 75) and attested at Susa.'),
 ('ENT_ELAM_TIRUTUR','PER_ELAM_CLASSICAL','Elamite god regularly paired with Tepti in Neo-Elamite royal inscriptions; in the Hanni of Ayapir text the kitin of Tepti and Tirutur is invoked with Napir, Simut and Humban.'),
 ('ENT_ELAM_SUHSIPA','PER_ELAM_CLASSICAL','Elamite deity with a temple at Dur-Untash (Tchoga Zanbil) alongside Lagamar and Napirisha; grouped by Henkelman among gods of the husa, a funerary/netherworld sphere.');
