INSERT INTO _r VALUES
 ('ENT_ARA_DUSHARA','member_of','ENT_NAB_PANTHEON','high','Dushara is the supreme dynastic god of the Nabataeans, attested at Petra, Bostra and Hegra.','SRC_HEALEY_NABATAEAN_RELIGION'),
