 ('ENT_SAB_DHAT_HIMYAM','embodies','ENT_SUN','medium','Solar ''Lady'', a hypostasis of the sun-goddess Shams.',''),
 ('ENT_SAB_DHAT_HIMYAM','aligned_with','ENT_SAB_SHAMS','medium','Dhat-Himyam is a solar hypostasis of Shams.',''),
 ('ENT_SAB_DHAT_BADAN','embodies','ENT_SUN','medium','Second solar ''Lady'' of the Sabaean pantheon.',''),
